package app.loveu;
import org.json.*;
public final class SharedCoupleRecordsTest {
 static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
 static JSONObject state()throws Exception{return new JSONObject().put("id","a").put("peer",new JSONObject().put("id","b")).put("events",new JSONArray().put(new JSONObject().put("secret","retained"))).put("menstrualSelf",new JSONArray().put("personal"));}
 static JSONObject op(String type,String subject,String source,String action,long clock,String id,JSONObject data)throws Exception{return new JSONObject().put("kind","sharedRecord").put("recordType",type).put("subject",subject).put("sourceId",source).put("action",action).put("clock",clock).put("operationId",id).put("data",data);}
 static JSONObject period()throws Exception{return new JSONObject().put("start","2026-10-01").put("end",JSONObject.NULL).put("flow","中").put("pain","轻度");}
 static JSONObject item(JSONObject c)throws Exception{return c.getJSONObject("sharedRecords").getJSONObject("period:a:2026-10-01");}
 static String canonical(JSONObject j){return j.toMap().toString();}
 public static void main(String[] args)throws Exception{
  JSONObject raw=new JSONObject().put("date","2026-10-01").put("note","private").put("unknown","private").put("place","secret").put("latitude",1).put("selfCondition",new JSONObject().put("note","private"));String before=raw.toString();JSONObject safe=SharedCoupleRecords.snapshot(raw,"sex",false);check(!safe.has("note")&&!safe.has("unknown")&&safe.isNull("place")&&safe.isNull("latitude")&&!safe.has("selfCondition"),"whitelist default privacy");check(SharedCoupleRecords.snapshot(raw,"sex",true).has("latitude"),"explicit location opt-in");check(before.equals(raw.toString()),"snapshot retention");
  JSONObject a=state(),b=state();String personal=a.getJSONArray("events").toString(),localPeriod=a.getJSONArray("menstrualSelf").toString();JSONObject first=op("period","a","a:local1","share",1,"first",period()),second=op("period","a","b:local2","share",2,"second",period().put("flow","多")),edit=op("period","a","a:local1","edit",3,"edit",period().put("end","2026-10-05"));SharedCoupleRecords.apply(a,first,"a");SharedCoupleRecords.apply(a,second,"b");SharedCoupleRecords.apply(a,edit,"b");SharedCoupleRecords.apply(a,first,"a");SharedCoupleRecords.apply(b,edit,"b");SharedCoupleRecords.apply(b,second,"b");SharedCoupleRecords.apply(b,first,"a");check(canonical(item(a)).equals(canonical(item(b))),"duplicate/order convergence");check(a.getJSONObject("sharedRecords").length()==1,"same period merge");check("2026-10-05".equals(item(a).getJSONObject("data").getString("end")),"collaborative edits");
  JSONObject withdraw=op("period","a","a:local1","withdraw",4,"withdraw",period());SharedCoupleRecords.apply(a,withdraw,"a");SharedCoupleRecords.apply(a,edit,"b");SharedCoupleRecords.apply(b,withdraw,"a");check(item(a).optBoolean("withdrawn")&&item(a).getJSONObject("data").length()==0,"tombstone cannot resurrect");check(canonical(item(a)).equals(canonical(item(b))),"withdraw convergence");
  JSONObject empty=state();String untouched=empty.toString();try{SharedCoupleRecords.apply(empty,first,"outsider");throw new AssertionError("unknown accepted");}catch(SecurityException expected){}check(untouched.equals(empty.toString()),"auth reject atomic");JSONObject sex=op("sex","a","a:source","share",1,"sex",raw);try{SharedCoupleRecords.apply(empty,sex,"b");throw new AssertionError("forged sex share accepted");}catch(SecurityException expected){}check(untouched.equals(empty.toString()),"owner reject atomic");
  SharedCoupleRecords.apply(a,op("period","a","x","comment",5,"comment",period()).put("text","hello"),"b");check(item(a).getJSONObject("interactions").length()==0,"withdrawn thread stays absent");check(personal.equals(a.getJSONArray("events").toString())&&localPeriod.equals(a.getJSONArray("menstrualSelf").toString()),"personal arrays retained");
  JSONObject live=state();SharedCoupleRecords.apply(live,first,"a");JSONObject like=op("period","a","x","like",3,"like",period()).put("enabled",true),unlike=op("period","a","x","like",4,"unlike",period()).put("enabled",false);SharedCoupleRecords.apply(live,unlike,"b");SharedCoupleRecords.apply(live,like,"b");check(!item(live).getJSONObject("interactions").getJSONObject("b:like").getBoolean("enabled"),"reaction order");  JSONObject owner=state();SharedCoupleRecords.apply(owner,sex.put("includeLocation",true),"a");SharedCoupleRecords.apply(owner,op("sex","a","a:source","share",2,"private-again",raw),"a");check(owner.getJSONObject("sharedRecords").getJSONObject("sex:a:a:source").getJSONObject("data").isNull("place"),"location opt-out clears prior shared location");
  JSONObject early=state();SharedCoupleRecords.apply(early,withdraw,"a");SharedCoupleRecords.apply(early,first,"a");check(canonical(item(a)).equals(canonical(item(early))),"withdraw first convergence");
  JSONArray tags=new JSONArray().put("one");JSONObject copied=SharedCoupleRecords.snapshot(new JSONObject().put("date","2026-10-01").put("positions",tags),"sex",false);tags.put("two");check(copied.getJSONArray("positions").length()==1,"deep snapshot isolation");try{SharedCoupleRecords.snapshot(new JSONObject().put("date","2026-10-01").put("rating","five"),"sex",false);throw new AssertionError("bad type accepted");}catch(JSONException expected){}
  JSONObject receipt=op("period","a","x","received",7,"receipt",period()).put("receivedOperation","first"),earlyReceipt=state();SharedCoupleRecords.apply(earlyReceipt,receipt,"b");SharedCoupleRecords.apply(earlyReceipt,first,"a");SharedCoupleRecords.apply(earlyReceipt,receipt,"b");JSONObject lateReceipt=state();SharedCoupleRecords.apply(lateReceipt,first,"a");SharedCoupleRecords.apply(lateReceipt,receipt,"b");check(canonical(item(earlyReceipt)).equals(canonical(item(lateReceipt))),"receipt duplicate and before-share convergence");check(item(earlyReceipt).getJSONObject("receipts").length()==1,"receipt idempotence");
  System.out.println("PASS shared privacy, authenticated actors, ordering, duplication, tombstones, period merge, interactions and personal retention");
 }
}


